export declare const schema = "#graphql\n  scalar DateTime\n  scalar BigInt\n\n  type Query {\n    # Health check\n    health: HealthCheck!\n\n    # Tokens\n    token(address: String!): Token\n    tokens(\n      limit: Int = 20\n      offset: Int = 0\n      after: String\n      orderBy: TokenOrderBy = CREATED_AT_DESC\n      search: String\n      status: TokenStatus\n    ): TokenConnection!\n    trendingTokens(limit: Int = 10): [Token!]!\n\n    # Pools\n    pool(address: String!): Pool\n    pools(limit: Int = 20, offset: Int = 0): PoolConnection!\n\n    # Users\n    user(address: String!): User\n\n    # Leaderboard (optimized with cache)\n    leaderboard(\n      type: LeaderboardType = TRADERS\n      limit: Int = 100\n      timeframe: LeaderboardTimeframe = DAY\n    ): [LeaderboardEntry!]!\n\n    # Transactions\n    transactions(\n      address: String\n      tokenAddress: String\n      type: TransactionType\n      limit: Int = 20\n      offset: Int = 0\n    ): TransactionConnection!\n\n    # Stats\n    globalStats: GlobalStats!\n  }\n\n  type Mutation {\n    # Sync a token from blockchain to database\n    syncToken(tokenAddress: String!): Token!\n\n    # Admin: Delete a token from database (requires X-Admin-Key header)\n    deleteToken(tokenAddress: String!): DeleteTokenResult!\n\n    # Admin: Delete multiple tokens from database (requires X-Admin-Key header)\n    deleteTokensBatch(tokenAddresses: [String!]!): DeleteTokensBatchResult!\n  }\n\n  type DeleteTokenResult {\n    success: Boolean!\n    address: String!\n    message: String\n  }\n\n  type DeleteTokensBatchResult {\n    success: Boolean!\n    deletedCount: Int!\n    failedCount: Int!\n    results: [DeleteTokenResult!]!\n  }\n\n  type HealthCheck {\n    status: String!\n    timestamp: DateTime!\n    version: String!\n    database: Boolean!\n    cache: CacheStatus!\n  }\n\n  type CacheStatus {\n    available: Boolean!\n    type: String!\n  }\n\n  type Token {\n    id: ID!\n    address: String!\n    creator: String!\n    name: String!\n    symbol: String!\n    decimals: Int!\n    totalSupply: String!\n    metadataUri: String!\n    imageUrl: String\n    logoUrl: String # Alias for imageUrl (frontend compatibility)\n    description: String\n\n    # Bonding curve\n    bondingCurve: String! # Alias for address (frontend compatibility)\n    circulatingSupply: String!\n    xlmReserve: String!\n    graduated: Boolean!\n    xlmRaised: String!\n    initialPrice: String # Initial bonding curve price\n\n    # Graduation info (only for graduated tokens)\n    ammPairAddress: String # AMM pair address after graduation (null if not graduated)\n    graduationEvent: GraduationEventInfo # Full graduation details\n\n    # Metrics\n    marketCap: String\n    currentPrice: String\n    priceChange24h: Float\n    volume24h: String!\n    volume7d: String!\n    holders: Int!\n    holders24h: Int # Holders in last 24h\n    holdersChange24h: Float # Percentage change in holders\n\n    # Social links (optional)\n    website: String\n    twitter: String\n    telegram: String\n    discord: String\n\n    # Timestamps\n    createdAt: DateTime!\n    updatedAt: DateTime!\n\n    # Relations (will use DataLoaders)\n    creatorUser: User\n    pools: [Pool!]!\n  }\n\n  type GraduationEventInfo {\n    id: ID!\n    type: GraduationEventType!\n    ammPairAddress: String\n    lpTokensBurned: String\n    xlmRaised: String\n    tokensGraduated: String\n    timestamp: DateTime!\n    txHash: String\n    blockNumber: String\n  }\n\n  enum GraduationEventType {\n    GRADUATED\n    GRADUATION_DETAILED\n    GRADUATION_FAILED\n    TOKEN_RECOVERED\n    GRADUATION_RETRIED\n    BRIDGE_GRADUATION\n    GRADUATION_WITH_ASTRO\n  }\n\n  type Pool {\n    id: ID!\n    address: String!\n    token0Address: String!\n    token1Address: String!\n    reserve0: String!\n    reserve1: String!\n    totalSupply: String!\n    liquidity: String! # Alias for totalSupply (frontend compatibility)\n\n    # Metrics\n    tvl: String\n    volume24h: String!\n    volume7d: String!\n    volumeChange24h: Float # Volume change percentage\n    apr: Float\n    apy: Float # Alias for apr (frontend compatibility)\n    fee: String # Pool fee percentage\n\n    createdAt: DateTime!\n    updatedAt: DateTime!\n\n    # Relations (will use DataLoaders)\n    token0: Token!\n    token1: Token!\n  }\n\n  type User {\n    id: ID!\n    address: String!\n\n    # Gamification\n    points: Int!\n    level: Int!\n    referrals: Int!\n\n    # Stats\n    tokensCreatedCount: Int!\n    totalVolumeTraded: String!\n    totalLiquidityProvided: String!\n\n    # Relations\n    tokensCreated: [Token!]!\n    achievements: [Achievement!]!\n\n    createdAt: DateTime!\n    updatedAt: DateTime!\n  }\n\n  type Achievement {\n    id: ID!\n    achievementId: String!\n    name: String!\n    description: String!\n    imageUrl: String!\n    progress: Int!\n    maxProgress: Int!\n    completed: Boolean!\n    unlockedAt: DateTime\n  }\n\n  type Transaction {\n    id: ID!\n    hash: String!\n    type: TransactionType!\n    from: String!\n    to: String\n    tokenAddress: String\n    amount: String\n    grossAmount: String\n    netAmount: String\n    protocolFee: String\n    lpFee: String\n    status: TransactionStatus!\n    timestamp: DateTime!\n\n    # Relations\n    token: Token\n    user: User\n  }\n\n  type LeaderboardEntry {\n    rank: Int!\n    address: String!\n    user: User!\n\n    # Metrics (depende del tipo de leaderboard)\n    volume24h: String!\n    trades24h: Int!\n    profitLoss24h: String!\n\n    # Para CREATORS\n    tokensCreated: Int\n    totalVolumeGenerated: String\n\n    # Para LIQUIDITY_PROVIDERS\n    totalLiquidity: String\n    feesEarned24h: String\n\n    # Cambios\n    volumeChange24h: Float\n    rankChange24h: Int\n  }\n\n  type GlobalStats {\n    totalTokens: Int!\n    totalPools: Int!\n    totalUsers: Int!\n    totalVolume24h: String!\n    totalTVL: String!\n  }\n\n  # Pagination types\n  type TokenConnection {\n    edges: [TokenEdge!]!\n    pageInfo: PageInfo!\n    totalCount: Int!\n  }\n\n  type TokenEdge {\n    cursor: String!\n    node: Token!\n  }\n\n  type PoolConnection {\n    edges: [PoolEdge!]!\n    pageInfo: PageInfo!\n    totalCount: Int!\n  }\n\n  type PoolEdge {\n    cursor: String!\n    node: Pool!\n  }\n\n  type TransactionConnection {\n    edges: [TransactionEdge!]!\n    pageInfo: PageInfo!\n    totalCount: Int!\n  }\n\n  type TransactionEdge {\n    cursor: String!\n    node: Transaction!\n  }\n\n  type PageInfo {\n    hasNextPage: Boolean!\n    hasPreviousPage: Boolean!\n    startCursor: String\n    endCursor: String\n    total: Int!\n  }\n\n  # Enums\n  enum TokenOrderBy {\n    CREATED_AT_DESC\n    CREATED_AT_ASC\n    MARKET_CAP_DESC\n    VOLUME_DESC\n    HOLDERS_DESC\n    GRADUATION_DESC\n  }\n\n  enum TokenStatus {\n    ALL\n    BONDING\n    GRADUATED\n  }\n\n  enum LeaderboardType {\n    CREATORS\n    TRADERS\n    LIQUIDITY_PROVIDERS\n    VIRAL_TOKENS\n  }\n\n  enum LeaderboardTimeframe {\n    HOUR\n    DAY\n    WEEK\n    MONTH\n    ALL_TIME\n  }\n\n  enum TransactionType {\n    TOKEN_CREATED\n    TOKEN_BOUGHT\n    TOKEN_SOLD\n    LIQUIDITY_ADDED\n    LIQUIDITY_REMOVED\n    SWAP\n  }\n\n  enum TransactionStatus {\n    PENDING\n    SUCCESS\n    FAILED\n  }\n\n# ============================================================\n# FEE MANAGEMENT SCHEMA\n# ============================================================\n\n\"\"\"\nFee configuration from the smart contract\n\"\"\"\ntype FeeConfig {\n  \"\"\"Protocol fee in basis points (5 = 0.05%)\"\"\"\n  protocolFeeBps: Int!\n  \n  \"\"\"LP fee in basis points (25 = 0.25%)\"\"\"\n  lpFeeBps: Int!\n  \n  \"\"\"Creation fee in stroops (100000000 = 10 XLM)\"\"\"\n  creationFee: String!\n  \n  \"\"\"Multi-sig treasury address\"\"\"\n  treasuryAddress: String!\n  \n  \"\"\"When this configuration became effective\"\"\"\n  effectiveFrom: DateTime!\n  \n  \"\"\"Who updated this configuration\"\"\"\n  updatedBy: String\n  \n  \"\"\"Last update timestamp\"\"\"\n  updatedAt: DateTime!\n}\n\n\"\"\"\nComprehensive fee statistics\n\"\"\"\ntype FeeStats {\n  \"\"\"Token address (null for global stats)\"\"\"\n  tokenAddress: String\n  \n  # Protocol Fees (Revenue)\n  \"\"\"Total protocol fees collected (all time)\"\"\"\n  totalProtocolFees: String!\n  \n  \"\"\"Protocol fees in last 24 hours\"\"\"\n  protocolFees24h: String!\n  \n  \"\"\"Protocol fees in last 7 days\"\"\"\n  protocolFees7d: String!\n  \n  \"\"\"Protocol fees in last 30 days\"\"\"\n  protocolFees30d: String!\n  \n  # LP Fees (Liquidity)\n  \"\"\"Total LP fees collected (all time)\"\"\"\n  totalLpFees: String!\n  \n  \"\"\"LP fees in last 24 hours\"\"\"\n  lpFees24h: String!\n  \n  \"\"\"LP fees in last 7 days\"\"\"\n  lpFees7d: String!\n  \n  \"\"\"LP fees in last 30 days\"\"\"\n  lpFees30d: String!\n  \n  # Creation Fees\n  \"\"\"Total creation fees collected (all time)\"\"\"\n  totalCreationFees: String!\n  \n  \"\"\"Creation fees in last 24 hours\"\"\"\n  creationFees24h: String!\n  \n  \"\"\"Creation fees in last 7 days\"\"\"\n  creationFees7d: String!\n  \n  \"\"\"Creation fees in last 30 days\"\"\"\n  creationFees30d: String!\n  \n  # Totals\n  \"\"\"Total fees (protocol + LP + creation)\"\"\"\n  totalFees: String!\n  \n  \"\"\"Total fees in last 24 hours\"\"\"\n  totalFees24h: String!\n  \n  \"\"\"Total fees in last 7 days\"\"\"\n  totalFees7d: String!\n  \n  \"\"\"Total fees in last 30 days\"\"\"\n  totalFees30d: String!\n  \n  # Transaction Counts\n  \"\"\"Total number of fee-generating transactions\"\"\"\n  totalTransactions: Int!\n  \n  \"\"\"Transactions in last 24 hours\"\"\"\n  transactions24h: Int!\n  \n  \"\"\"Last update timestamp\"\"\"\n  updatedAt: DateTime!\n}\n\n\"\"\"\nIndividual fee collection record\n\"\"\"\ntype FeeCollection {\n  \"\"\"Unique identifier\"\"\"\n  id: ID!\n  \n  \"\"\"Transaction hash\"\"\"\n  hash: String!\n  \n  \"\"\"Fee type\"\"\"\n  type: FeeType!\n  \n  \"\"\"Token address\"\"\"\n  tokenAddress: String!\n  \n  \"\"\"Token details (resolved)\"\"\"\n  token: Token\n  \n  \"\"\"Fee amount in stroops\"\"\"\n  amount: String!\n  \n  \"\"\"Treasury address (for protocol fees)\"\"\"\n  treasuryAddress: String\n  \n  \"\"\"User who triggered the fee\"\"\"\n  userAddress: String!\n  \n  \"\"\"Transaction type (BUY/SELL/CREATE)\"\"\"\n  transactionType: String!\n  \n  # Breakdown\n  \"\"\"Amount before fees\"\"\"\n  grossAmount: String!\n  \n  \"\"\"Protocol fee amount\"\"\"\n  protocolFee: String\n  \n  \"\"\"LP fee amount\"\"\"\n  lpFee: String\n  \n  \"\"\"Amount after fees\"\"\"\n  netAmount: String!\n  \n  \"\"\"Block timestamp\"\"\"\n  timestamp: DateTime!\n  \n  \"\"\"Block number\"\"\"\n  blockNumber: String!\n  \n  \"\"\"Created at\"\"\"\n  createdAt: DateTime!\n}\n\n\"\"\"\nFee collection history with pagination\n\"\"\"\ntype FeeCollectionHistory {\n  \"\"\"List of fee collections\"\"\"\n  items: [FeeCollection!]!\n  \n  \"\"\"Total count\"\"\"\n  total: Int!\n  \n  \"\"\"Has more items\"\"\"\n  hasMore: Boolean!\n  \n  \"\"\"Pagination info\"\"\"\n  pageInfo: PageInfo!\n}\n\n\"\"\"\nRevenue breakdown by category\n\"\"\"\ntype RevenueCategory {\n  \"\"\"Total revenue (all time)\"\"\"\n  total: String!\n  \n  \"\"\"Revenue in last 24 hours\"\"\"\n  day: String!\n  \n  \"\"\"Revenue in last 7 days\"\"\"\n  week: String!\n  \n  \"\"\"Revenue in last 30 days\"\"\"\n  month: String!\n}\n\n\"\"\"\nTransaction count breakdown\n\"\"\"\ntype TransactionCount {\n  \"\"\"Total transactions\"\"\"\n  total: Int!\n  \n  \"\"\"Transactions in last 24 hours\"\"\"\n  day: Int!\n  \n  \"\"\"Transactions in last 7 days\"\"\"\n  week: Int!\n  \n  \"\"\"Transactions in last 30 days\"\"\"\n  month: Int!\n}\n\n\"\"\"\nComprehensive revenue breakdown\n\"\"\"\ntype RevenueBreakdown {\n  \"\"\"Protocol fees (team revenue)\"\"\"\n  protocolFees: RevenueCategory!\n  \n  \"\"\"LP fees (liquidity provision)\"\"\"\n  lpFees: RevenueCategory!\n  \n  \"\"\"Creation fees (anti-spam + revenue)\"\"\"\n  creationFees: RevenueCategory!\n  \n  \"\"\"Total revenue (all categories)\"\"\"\n  totalRevenue: RevenueCategory!\n  \n  \"\"\"Transaction counts\"\"\"\n  transactionCount: TransactionCount!\n}\n\n\"\"\"\nToken fee performance metrics\n\"\"\"\ntype TokenFeePerformance {\n  \"\"\"Token address\"\"\"\n  tokenAddress: String!\n  \n  \"\"\"Token details\"\"\"\n  token: Token\n  \n  \"\"\"Protocol fees generated\"\"\"\n  protocolFees: String!\n  \n  \"\"\"LP fees generated\"\"\"\n  lpFees: String!\n  \n  \"\"\"Total fees generated\"\"\"\n  totalFees: String!\n  \n  \"\"\"Number of transactions\"\"\"\n  transactionCount: Int!\n  \n  \"\"\"Average fee per transaction\"\"\"\n  avgFeePerTransaction: String!\n  \n  \"\"\"Rank in leaderboard\"\"\"\n  rank: Int!\n}\n\n\"\"\"\nRecent growth metrics\n\"\"\"\ntype RecentGrowth {\n  \"\"\"Protocol fees today\"\"\"\n  protocolFees: String!\n  \n  \"\"\"LP fees today\"\"\"\n  lpFees: String!\n  \n  \"\"\"Total fees today\"\"\"\n  totalFees: String!\n  \n  \"\"\"Percentage change vs 7-day average\"\"\"\n  percentageChange: Float!\n}\n\n\"\"\"\nFee dashboard summary\n\"\"\"\ntype FeeDashboard {\n  \"\"\"Revenue breakdown\"\"\"\n  revenue: RevenueBreakdown!\n  \n  \"\"\"Top 5 tokens by fees\"\"\"\n  topTokens: [TokenFeePerformance!]!\n  \n  \"\"\"Recent growth metrics\"\"\"\n  recentGrowth: RecentGrowth!\n  \n  \"\"\"Timestamp of data\"\"\"\n  timestamp: DateTime!\n}\n\n\"\"\"\nAverage fee per transaction\n\"\"\"\ntype AverageFee {\n  \"\"\"Average protocol fee\"\"\"\n  protocolFee: String!\n  \n  \"\"\"Average LP fee\"\"\"\n  lpFee: String!\n  \n  \"\"\"Average total fee\"\"\"\n  totalFee: String!\n}\n\n\"\"\"\nGeneric mutation response\n\"\"\"\ntype MutationResponse {\n  \"\"\"Success flag\"\"\"\n  success: Boolean!\n  \n  \"\"\"Response message\"\"\"\n  message: String!\n  \n  \"\"\"Number of items updated (optional)\"\"\"\n  updated: Int\n}\n\n# ============================================================\n# ENUMS\n# ============================================================\n\n\"\"\"\nFee type enumeration\n\"\"\"\nenum FeeType {\n  PROTOCOL_FEE\n  LP_FEE\n  CREATION_FEE\n  PROTOCOL_FEE_BUY\n  PROTOCOL_FEE_SELL\n  LP_FEE_BUY\n  LP_FEE_SELL\n}\n\n\"\"\"\nTime window for statistics\n\"\"\"\nenum TimeWindow {\n  DAY\n  WEEK\n  MONTH\n  ALL\n}\n\n# ============================================================\n# INPUT TYPES\n# ============================================================\n\n\"\"\"\nInput for token-specific fee stats\n\"\"\"\ninput FeeStatsInput {\n  \"\"\"Token address (required)\"\"\"\n  tokenAddress: String!\n}\n\n\"\"\"\nInput for top tokens query\n\"\"\"\ninput TopTokensByFeesInput {\n  \"\"\"Number of tokens to return (max 100)\"\"\"\n  limit: Int = 10\n  \n  \"\"\"Time window for ranking\"\"\"\n  timeWindow: TimeWindow = ALL\n}\n\n\"\"\"\nInput for fee collection history\n\"\"\"\ninput FeeHistoryInput {\n  \"\"\"Filter by token address\"\"\"\n  tokenAddress: String\n  \n  \"\"\"Filter by fee type\"\"\"\n  type: FeeType\n  \n  \"\"\"Number of items per page (max 100)\"\"\"\n  limit: Int = 50\n  \n  \"\"\"Offset for pagination\"\"\"\n  offset: Int = 0\n  \n  \"\"\"Start date filter (ISO 8601)\"\"\"\n  startDate: DateTime\n  \n  \"\"\"End date filter (ISO 8601)\"\"\"\n  endDate: DateTime\n}\n\n\"\"\"\nInput for recalculating fee stats\n\"\"\"\ninput RecalculateFeeStatsInput {\n  \"\"\"Include token-specific stats\"\"\"\n  includeTokenStats: Boolean = true\n  \n  \"\"\"Include global stats\"\"\"\n  includeGlobalStats: Boolean = true\n}\n\n# ============================================================\n# QUERIES (EXTENSIONS)\n# ============================================================\n\nextend type Query {\n  \"\"\"\n  Get global fee statistics (all tokens combined)\n  Cache TTL: 30 seconds\n  \"\"\"\n  globalFeeStats: FeeStats!\n  \n  \"\"\"\n  Get fee statistics for a specific token\n  Cache TTL: 30 seconds\n  \"\"\"\n  tokenFeeStats(input: FeeStatsInput!): FeeStats\n  \n  \"\"\"\n  Get comprehensive revenue breakdown\n  Cache TTL: 60 seconds\n  \"\"\"\n  revenueBreakdown: RevenueBreakdown!\n  \n  \"\"\"\n  Get top tokens ranked by fee generation\n  Cache TTL: 120 seconds\n  \"\"\"\n  topTokensByFees(input: TopTokensByFeesInput): [TokenFeePerformance!]!\n  \n  \"\"\"\n  Get fee collection history with pagination\n  Cache TTL: 300 seconds\n  \"\"\"\n  feeCollectionHistory(input: FeeHistoryInput): FeeCollectionHistory!\n  \n  \"\"\"\n  Get fee dashboard summary (revenue, top tokens, growth)\n  Cache TTL: 30 seconds\n  \"\"\"\n  feeDashboard: FeeDashboard!\n  \n  \"\"\"\n  Get average fee per transaction\n  Cache TTL: 60 seconds\n  \"\"\"\n  averageFeePerTransaction(input: FeeStatsInput): AverageFee!\n  \n  \"\"\"\n  Get current fee configuration from contract\n  Cache TTL: 300 seconds\n  \"\"\"\n  feeConfig: FeeConfig!\n}\n\n# ============================================================\n# MUTATIONS (EXTENSIONS)\n# ============================================================\n\nextend type Mutation {\n  \"\"\"\n  Recalculate fee statistics from source data\n  Admin only - requires authentication\n  \"\"\"\n  recalculateFeeStats(input: RecalculateFeeStatsInput): MutationResponse!\n  \n  \"\"\"\n  Reset expired time windows (daily maintenance)\n  Admin only - requires authentication\n  \"\"\"\n  resetExpiredTimeWindows: MutationResponse!\n}\n";
